sections = (function () {
  var parsed = JSON.parse(String(sectionsJson));
  var out = [];
  for (var i = 0; i < parsed.sections.length; i++) {
    var s = parsed.sections[i];
    if (!String(s.content || '').trim()) { continue; }
    var title = String(s.title || ('section-' + s.index));
    out.push({
      title: title,
      content: String(s.content),
      slug: ('0' + (out.length + 1)).slice(-2) + '-' + title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
    });
  }
  if (out.length === 0) { throw 'No sections with content found in the document'; }
  return out;
})();
